"use client";

import React, { useEffect, useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useSocket } from "@/contexts/SocketContext";
import UserList from "@/components/UserList";
import VideoCallModal from "@/components/VideoCallModal";

export default function CallPage() {
  const { user, loading } = useAuth();
  const socket = useSocket();
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [callData, setCallData] = useState(null);

  useEffect(() => {
    if (!socket || !user) return;

    socket.emit("join", user.id);
    socket.on("user_online", (list) =>
      setOnlineUsers(list.filter((id) => id !== user.id))
    );
    socket.on("incoming_call", (data) =>
      setCallData({ ...data, incoming: true })
    );

    return () => {
      socket.off("user_online");
      socket.off("incoming_call");
    };
  }, [socket, user]);

  if (loading || !socket) return <p className="text-white">Loading…</p>;

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4 text-white">Start a Call</h1>
      <UserList
        users={onlineUsers}
        onCall={(to) => setCallData({ to, from: user.id, incoming: false })}
      />
      {callData && (
        <VideoCallModal
          socket={socket}
          user={user}
          callData={callData}
          onClose={() => setCallData(null)}
        />
      )}
    </div>
  );
}
